// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealthz)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/register", wrapper.Register)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/me", wrapper.UpdateMe)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/activities", wrapper.CreateActivity)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/activities/uploads", wrapper.UploadActivity)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/garmin", wrapper.DeleteGarminConnection)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/garmin", wrapper.GetGarminConnection)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/garmin/key", wrapper.SetGarminKey)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/garmin/sync-interval", wrapper.SetGarminSyncInterval)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/garmin/backfill", wrapper.GetGarminBackfill)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/garmin/backfill", wrapper.StartGarminBackfill)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/garmin/backfill/resume", wrapper.ResumeGarminBackfill)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/garmin/backfill/failures", wrapper.ListGarminBackfillFailures)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/garmin/sync", wrapper.SyncGarmin)
	})

	return r
}

